import React, { useMemo } from "react";

import formTemplate from "../../config/application-form--template";
import { publickey } from "../../config/gforms--publickey";
import ApplicationForm from "../../modules/application/ApplicationForm";
import type { GFormField } from "../../modules/gh-leads/GForm";
import { useActiveApplication } from "./useActiveApplication";
import { useCatalogue } from "../property/useCatalogue";
import type { PropertyRecord } from "../../modules/property/types";
import {
  requiresPublicKey,
  useHandleSubmitForm,
} from "../../modules/gforms/handleSubmitForm";
import { bedroomRange, publishedOnly } from "../../modules/property/derive";
import { catalogue } from "../property/catalogue";
import applicationEnabled from "../../toggles/application";

/**
 * The rental application form, as data.
 *
 * This array IS the form. Adding, removing or reordering a question is an edit
 * here and nothing else — no markup, no styling, no validation code. The same
 * shape is what the CMS will eventually store, so an editor can manage the
 * questions without touching source.
 *
 * Nothing here asks for sensitive information: no bank details, no social
 * security number, no card details. Those belong in a secured flow the client
 * has signed off on, never in a public form posting to a spreadsheet.
 */
/* ── the two lists that have to match reality ─────────────
   Both of these were written by hand, and both had drifted. The property list
   named five of the twelve this business manages, so seven could not be
   applied for at all, and nothing would have corrected it when a property was
   added, renamed or taken off the website. The size list stopped at three
   bedrooms, which no longer matched the catalogue either.

   Built from the same catalogue the website renders, so an applicant is
   offered what actually exists and the lists cannot go stale again. */

/** Published properties, in catalogue order, with a way out at the end. */
function propertyOptions(records: PropertyRecord[] = catalogue): { label: string; value: string }[] {
  const options = publishedOnly(records).map((property) => ({
    label: property.title,
    value: property.slug,
  }));

  /* Last, and always present. Somebody enquiring before they have chosen is
     the normal case, not an edge case. */
  return [...options, { label: "Not sure yet", value: "undecided" }];
}

const SIZE_WORDS = [
  "Studio",
  "One Bedroom",
  "Two Bedroom",
  "Three Bedroom",
  "Four Bedroom",
  "Five Bedroom",
  "Six Bedroom",
];

/**
 * The sizes that actually exist, smallest first.
 *
 * Read from the properties rather than listed, so a six-bedroom house added
 * next year appears here without anybody remembering to come back. A property
 * with floor plans contributes every size among them, which is the whole
 * point of having plans.
 *
 * Deliberately not narrowed to the property chosen above: these are two
 * independent answers on one form, and an applicant who picks a size first
 * must not find the list changing underneath them. The team confirms the
 * match when they follow up - which the note under the form already says.
 */
function homeSizeOptions(records: PropertyRecord[] = catalogue): { label: string; value: string }[] {
  /* Studio to five bedrooms, always. The catalogue tops out at three today,
     and an applicant who needs four should still be able to say so rather
     than being told, by omission, that this business does not do that. The
     catalogue can only ADD to this list, never shorten it. */
  const sizes = new Set<number>([0, 1, 2, 3, 4, 5]);

  for (const property of publishedOnly(records)) {
    const range = bedroomRange(property);

    if (range) {
      for (let beds = range.min; beds <= range.max; beds += 1) sizes.add(beds);
    } else if (typeof property.bedrooms === "number") {
      sizes.add(property.bedrooms);
    }
  }

  return [...sizes].sort((a, b) => a - b).map(sizeOption);
}

const sizeOption = (beds: number) => ({
  label: SIZE_WORDS[beds] ?? `${beds} Bedroom`,
  value: beds === 0 ? "studio" : `${beds}-bedroom`,
});

