/**
 * The application form, configured.
 *
 * Submission goes through the existing PPM handler, which encrypts values with
 * the site's public key before they leave the browser. That key is still a
 * TODO(client) placeholder, so rather than appearing to succeed and dropping
 * the applicant's details on the floor, an unconfigured form says so.
 */
export default function ApplicationX() {
  const { handleSubmitForm } = useHandleSubmitForm();

  const { data: records } = useCatalogue();
  const { data: active, error } = useActiveApplication();
  const fields = useMemo(() => applicationFields.map((field) => {
    if (field.name === "property") return { ...field, options: propertyOptions(records) };
    if (field.name === "homeType") return { ...field, options: homeSizeOptions(records) };
    return field;
  }), [records]);

  const onSubmit = async (values: Record<string, unknown>) => {
    /* Only the encrypting transport needs a key. Supabase does not, and
       demanding one there would refuse a form that works perfectly. */
    if (requiresPublicKey() && (!publickey || !publickey.trim())) {
      throw new Error(
        "This form is not connected yet. Please call or email us and we will take your application directly."
      );
    }

    /* Naming the application means a submission can be shown against the
       questions it was actually answering, however they change later. */
    const outcome = await handleSubmitForm(
      values,
      publickey,
      undefined,
      /* `kind` is set whether or not the Builder has an active application.
         It used to be that only a remotely-loaded application named itself,
         so a site whose Builder had never been saved recorded nothing at all
         and every application looked like an enquiry in the CMS. */
      active
        ? { id: active.id, name: active.name, kind: "application" as const }
        : { kind: "application" as const }
    );

    /* The shared handler RETURNS a failure rather than throwing one, and the
       form shows its success screen for anything that does not throw. Without
       this, a rejected submission would tell somebody their application had
       been received — the same defect the contact form fixed, and a worse one
       here, because an applicant who believes they have applied stops
       chasing it. */
    if (outcome && outcome.success === false) {
      throw new Error(
        "Your application could not be sent — the connection failed. Please try again, or call us and we will take it directly."
      );
    }
  };

  if (!applicationEnabled) return null;

  return (
    <>
    {error && <p role="status">{error}</p>}
    <ApplicationForm
      fields={active ? active.questions : fields}
      formTemplate={formTemplate}
      submitLabel="Submit Application"
      note="Submitting this form does not reserve a property. A member of the team will follow up to confirm the next steps and anything else required."
      onSubmit={onSubmit}
    />
    </>
  );
}
