import React from "react";
import Seo from "../components/Seo";
import type { HeadFC, PageProps } from "gatsby";
import { LuCheck, LuMail, LuPhone } from "react-icons/lu";

import Layout from "../components/Layout";
import applicationTemplate from "../ppm/config/application--template";
import {
  EMAIL,
  EMAIL_HREF,
  PHONE_DISPLAY,
  PHONE_HREF,
} from "../ppm/config/profile--contact";
import ApplicationBannerX from "../ppm/primitives/application/application-banner-x";
import ApplicationX from "../ppm/primitives/application/application-x";

/** What an applicant should have to hand. Neutral - no policy is stated. */
const requirements = [
  "Contact details for everyone who will live in the home",
  "Your preferred property and move-in timing",
  "Details of any pets, if applicable",
  "Anything else you would like the team to know",
];

/**
 * The rental application page.
 *
 * The form is entirely data-driven: see applicationFields in
 * primitives/application/application-x. This file is the page around it.
 */
export default function ApplyPage(_props: PageProps) {
  return (
    <Layout>
      <style>{applicationTemplate.css}</style>

      <ApplicationBannerX />

      <section className="kr-apply">
        <div className="kr-apply__inner">
          <ApplicationX />

          <aside className="kr-apply__aside">
            <h2 className="kr-apply__aside-title">What you will need</h2>
            <ul className="kr-apply__aside-list">
              {requirements.map((item) => (
                <li key={item}>
                  <span className="kr-apply__aside-icon" aria-hidden="true">
                    <LuCheck size={15} strokeWidth={2} />
                  </span>
                  {item}
                </li>
              ))}
            </ul>

            <div className="kr-apply__aside-divider" />

            <h2 className="kr-apply__aside-title">Prefer to talk it through?</h2>
            <p className="kr-apply__aside-text">
              If you would rather apply over the phone, or have a question first,
              get in touch and we will help.
            </p>
            <ul className="kr-apply__aside-list">
              <li>
                <span className="kr-apply__aside-icon" aria-hidden="true">
                  <LuPhone size={15} strokeWidth={1.5} />
                </span>
                <a href={PHONE_HREF}>{PHONE_DISPLAY}</a>
              </li>
              <li>
                <span className="kr-apply__aside-icon" aria-hidden="true">
                  <LuMail size={15} strokeWidth={1.5} />
                </span>
                <a href={EMAIL_HREF}>{EMAIL}</a>
              </li>
            </ul>
          </aside>
        </div>
      </section>
    </Layout>
  );
}

export const Head: HeadFC = () => (
  <Seo
    title="Apply | Kelley Road Property Management"
    description={"Apply for a Kelley Road managed home. Tell us about yourself and the property you are interested in, and the team will follow up."}
    pathname="/apply/"
  />
);
